-- DSOA cost estimate (generated by src/build/generate_cost_calculator.py - do not edit, change cost_model.yml and rebuild)
-- READ-ONLY: creates nothing. Run in a Snowsight worksheet with a role that can read the SNOWFLAKE database
-- (for example ACCOUNTADMIN, or a role granted IMPORTED PRIVILEGES on SNOWFLAKE). The script first checks that it can read the
-- required ACCOUNT_USAGE views and, if not, returns one MISSING PERMISSIONS row instead of the report. See docs/COST_ESTIMATE.md.
-- Assumes all plugins enabled with shipped defaults. Sources that cannot be read are shown as "n/a" with the reason.
-- The scan covers the last 7 days of ACCOUNT_USAGE, QUERY_HISTORY and the account event table.
EXECUTE IMMEDIATE $$
DECLARE
-- ===== RATE CARD (edit prices here, nothing else needs to change) =====
-- As of 2026-11-02, USD. Source: Dynatrace public DPS rate card - VERIFY every value before publishing (open point in BIZOBS-3285)
-- Contract prices: replace the values below. Retention is the number of days kept in Grail.
  p_logs_gib FLOAT DEFAULT 0.2; -- Logs: ingest & process, per GiB
  p_spans_gib FLOAT DEFAULT 0.2; -- Traces/spans: ingest & process, per GiB
  p_events_gib FLOAT DEFAULT 0.2; -- Events: ingest & process, per GiB
  p_bizevents_gib FLOAT DEFAULT 0.2; -- Business events: ingest & process, per GiB
  p_metrics_100k FLOAT DEFAULT 0.15; -- Metrics: ingest & process, per 100k data points
  p_retain_gib_day FLOAT DEFAULT 0.0007; -- Retain, per GiB per day (all signals)
  p_retention_days FLOAT DEFAULT 365; -- retention in days
-- ===== MEASURED INPUTS (filled by the script, 7-day lookback scaled to per day) =====
  v_tables_in_scope FLOAT DEFAULT 0; n_tables_in_scope VARCHAR DEFAULT 'measured'; -- tables in default data_volume / table_health scope
  v_dynamic_tables FLOAT DEFAULT 0; n_dynamic_tables VARCHAR DEFAULT 'measured'; -- dynamic tables outside DTAGENT_DB
  v_pipes FLOAT DEFAULT 0; n_pipes VARCHAR DEFAULT 'measured'; -- Snowpipes outside DTAGENT_DB
  v_warehouses FLOAT DEFAULT 1; n_warehouses VARCHAR DEFAULT 'measured'; -- warehouses with metering in the last 7 days
  v_resource_monitors FLOAT DEFAULT 1; n_resource_monitors VARCHAR DEFAULT 'measured'; -- resource monitors
  v_users FLOAT DEFAULT 0; n_users VARCHAR DEFAULT 'measured'; -- active users
  v_share_grants_out FLOAT DEFAULT 0; n_share_grants_out VARCHAR DEFAULT 'measured'; -- grants to outbound shares
  v_tables_in_shares FLOAT DEFAULT 0; n_tables_in_shares VARCHAR DEFAULT 'measured'; -- tables in inbound shares
  v_trust_center_findings FLOAT DEFAULT 0; n_trust_center_findings VARCHAR DEFAULT 'measured'; -- Trust Center findings
  v_queries_day FLOAT DEFAULT 0; n_queries_day VARCHAR DEFAULT 'measured'; -- queries per day (excluding DTAGENT_WH)
  v_slow_queries_day FLOAT DEFAULT 0; n_slow_queries_day VARCHAR DEFAULT 'measured'; -- queries per day slower than slow_queries_threshold (10 s)
  v_log_rows_day FLOAT DEFAULT 0; n_log_rows_day VARCHAR DEFAULT 'measured'; -- event table log rows per day
  v_span_rows_day FLOAT DEFAULT 0; n_span_rows_day VARCHAR DEFAULT 'measured'; -- event table span rows per day
  v_metric_rows_day FLOAT DEFAULT 0; n_metric_rows_day VARCHAR DEFAULT 'measured'; -- event table metric rows per day
  v_logins_day FLOAT DEFAULT 0; n_logins_day VARCHAR DEFAULT 'measured'; -- logins per day
  v_sessions_day FLOAT DEFAULT 0; n_sessions_day VARCHAR DEFAULT 'measured'; -- sessions per day
  v_task_runs_day FLOAT DEFAULT 0; n_task_runs_day VARCHAR DEFAULT 'measured'; -- task runs per day
  v_files_loaded_day FLOAT DEFAULT 0; n_files_loaded_day VARCHAR DEFAULT 'measured'; -- files loaded by Snowpipe/COPY per day
  v_ddl_day FLOAT DEFAULT 0; n_ddl_day VARCHAR DEFAULT 'measured'; -- DDL statements per day
  v_dt_refreshes_day FLOAT DEFAULT 0; n_dt_refreshes_day VARCHAR DEFAULT 'measured'; -- dynamic table refreshes per day
  v_const FLOAT DEFAULT 1;
  v_org FLOAT DEFAULT 0; n_org VARCHAR DEFAULT 'measured'; -- 1 when this is an organization account
  v_actual_credits FLOAT; v_actual_days FLOAT; n_actual_credits VARCHAR DEFAULT 'not installed';
  v_actual_records FLOAT; v_actual_rec_days FLOAT; n_actual_records VARCHAR DEFAULT 'not installed';
  v_probe FLOAT; v_role VARCHAR; v_failed FLOAT DEFAULT 0; v_missing VARCHAR DEFAULT ''; v_message VARCHAR;
  res_denied RESULTSET;
  res RESULTSET;
BEGIN
  SELECT CURRENT_ROLE() INTO :v_role;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.TABLES LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.TABLES; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.PIPES LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.PIPES; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.USERS LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.USERS; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.GRANTS_TO_SHARES LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.GRANTS_TO_SHARES; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.DATABASES LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.DATABASES; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.LOGIN_HISTORY LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.LOGIN_HISTORY; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.SESSIONS LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.SESSIONS; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY; ';
  END;
  BEGIN
    SELECT COUNT(*) INTO :v_probe FROM (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.COPY_HISTORY LIMIT 1);
  EXCEPTION WHEN OTHER THEN
    v_failed := v_failed + 1; v_missing := v_missing || 'SNOWFLAKE.ACCOUNT_USAGE.COPY_HISTORY; ';
  END;
  IF (v_failed > 0) THEN
    v_message := 'Cannot run the DSOA cost estimate: the current role ' || v_role || ' cannot read ' || v_failed || ' of 11 required sources: ' || v_missing
      || 'Run the script with a role that can read the SNOWFLAKE database (for example ACCOUNTADMIN), or ask an account admin to run: '
      || 'GRANT IMPORTED PRIVILEGES ON DATABASE SNOWFLAKE TO ROLE ' || v_role || ';';
    res_denied := (SELECT 'MISSING PERMISSIONS' AS STATUS, :v_message AS MESSAGE);
    RETURN TABLE(res_denied);
  END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_tables_in_scope FROM SNOWFLAKE.ACCOUNT_USAGE.TABLES WHERE DELETED IS NULL AND TABLE_SCHEMA <> 'INFORMATION_SCHEMA' AND TABLE_NAME NOT LIKE 'TMP!_%' ESCAPE '!' AND (TABLE_CATALOG = 'DTAGENT_DB' OR TABLE_SCHEMA = 'PUBLIC');
  EXCEPTION WHEN OTHER THEN
    v_tables_in_scope := 0; n_tables_in_scope := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_tables_in_scope IS NULL) THEN v_tables_in_scope := 0; n_tables_in_scope := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_dynamic_tables FROM SNOWFLAKE.ACCOUNT_USAGE.TABLES WHERE DELETED IS NULL AND IS_DYNAMIC = 'YES' AND TABLE_CATALOG <> 'DTAGENT_DB';
  EXCEPTION WHEN OTHER THEN
    v_dynamic_tables := 0; n_dynamic_tables := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_dynamic_tables IS NULL) THEN v_dynamic_tables := 0; n_dynamic_tables := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_pipes FROM SNOWFLAKE.ACCOUNT_USAGE.PIPES WHERE DELETED IS NULL AND PIPE_CATALOG <> 'DTAGENT_DB';
  EXCEPTION WHEN OTHER THEN
    v_pipes := 0; n_pipes := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_pipes IS NULL) THEN v_pipes := 0; n_pipes := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(DISTINCT WAREHOUSE_NAME) INTO :v_warehouses FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY WHERE START_TIME >= DATEADD(day, -7, CURRENT_TIMESTAMP()) AND WAREHOUSE_NAME <> 'DTAGENT_WH';
  EXCEPTION WHEN OTHER THEN
    v_warehouses := 1; n_warehouses := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_warehouses IS NULL) THEN v_warehouses := 1; n_warehouses := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_resource_monitors FROM SNOWFLAKE.ACCOUNT_USAGE.RESOURCE_MONITORS;
  EXCEPTION WHEN OTHER THEN
    v_resource_monitors := 1; n_resource_monitors := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_resource_monitors IS NULL) THEN v_resource_monitors := 1; n_resource_monitors := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_users FROM SNOWFLAKE.ACCOUNT_USAGE.USERS WHERE DELETED_ON IS NULL;
  EXCEPTION WHEN OTHER THEN
    v_users := 0; n_users := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_users IS NULL) THEN v_users := 0; n_users := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_share_grants_out FROM SNOWFLAKE.ACCOUNT_USAGE.GRANTS_TO_SHARES WHERE DELETED_ON IS NULL;
  EXCEPTION WHEN OTHER THEN
    v_share_grants_out := 0; n_share_grants_out := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_share_grants_out IS NULL) THEN v_share_grants_out := 0; n_share_grants_out := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_tables_in_shares FROM SNOWFLAKE.ACCOUNT_USAGE.TABLES WHERE DELETED IS NULL AND TABLE_CATALOG IN (SELECT DATABASE_NAME FROM SNOWFLAKE.ACCOUNT_USAGE.DATABASES WHERE TYPE = 'IMPORTED DATABASE' AND DELETED IS NULL);
  EXCEPTION WHEN OTHER THEN
    v_tables_in_shares := 0; n_tables_in_shares := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_tables_in_shares IS NULL) THEN v_tables_in_shares := 0; n_tables_in_shares := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_trust_center_findings FROM SNOWFLAKE.TRUST_CENTER.FINDINGS;
  EXCEPTION WHEN OTHER THEN
    v_trust_center_findings := 0; n_trust_center_findings := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_trust_center_findings IS NULL) THEN v_trust_center_findings := 0; n_trust_center_findings := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) / 7, COUNT_IF(TOTAL_ELAPSED_TIME > 10000) / 7, COUNT_IF(REGEXP_LIKE(QUERY_TYPE, '^(CREATE|ALTER|DROP).*')) / 7 INTO :v_queries_day, :v_slow_queries_day, :v_ddl_day FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE START_TIME >= DATEADD(day, -7, CURRENT_TIMESTAMP()) AND WAREHOUSE_NAME IS DISTINCT FROM 'DTAGENT_WH';
  EXCEPTION WHEN OTHER THEN
    v_queries_day := 0; n_queries_day := 'n/a, using default: ' || SQLERRM;
    v_slow_queries_day := 0; n_slow_queries_day := 'n/a, using default: ' || SQLERRM;
    v_ddl_day := 0; n_ddl_day := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_queries_day IS NULL) THEN v_queries_day := 0; n_queries_day := 'n/a, no data returned, using default'; END IF;
  IF (v_slow_queries_day IS NULL) THEN v_slow_queries_day := 0; n_slow_queries_day := 'n/a, no data returned, using default'; END IF;
  IF (v_ddl_day IS NULL) THEN v_ddl_day := 0; n_ddl_day := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT_IF(RECORD_TYPE = 'LOG') / 7, COUNT_IF(RECORD_TYPE IN ('SPAN', 'SPAN_EVENT')) / 7, COUNT_IF(RECORD_TYPE = 'METRIC') / 7 INTO :v_log_rows_day, :v_span_rows_day, :v_metric_rows_day FROM SNOWFLAKE.TELEMETRY.EVENTS WHERE TIMESTAMP >= DATEADD(day, -7, CURRENT_TIMESTAMP());
  EXCEPTION WHEN OTHER THEN
    v_log_rows_day := 0; n_log_rows_day := 'n/a, using default: ' || SQLERRM;
    v_span_rows_day := 0; n_span_rows_day := 'n/a, using default: ' || SQLERRM;
    v_metric_rows_day := 0; n_metric_rows_day := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_log_rows_day IS NULL) THEN v_log_rows_day := 0; n_log_rows_day := 'n/a, no data returned, using default'; END IF;
  IF (v_span_rows_day IS NULL) THEN v_span_rows_day := 0; n_span_rows_day := 'n/a, no data returned, using default'; END IF;
  IF (v_metric_rows_day IS NULL) THEN v_metric_rows_day := 0; n_metric_rows_day := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) / 7 INTO :v_logins_day FROM SNOWFLAKE.ACCOUNT_USAGE.LOGIN_HISTORY WHERE EVENT_TIMESTAMP >= DATEADD(day, -7, CURRENT_TIMESTAMP());
  EXCEPTION WHEN OTHER THEN
    v_logins_day := 0; n_logins_day := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_logins_day IS NULL) THEN v_logins_day := 0; n_logins_day := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) / 7 INTO :v_sessions_day FROM SNOWFLAKE.ACCOUNT_USAGE.SESSIONS WHERE CREATED_ON >= DATEADD(day, -7, CURRENT_TIMESTAMP());
  EXCEPTION WHEN OTHER THEN
    v_sessions_day := 0; n_sessions_day := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_sessions_day IS NULL) THEN v_sessions_day := 0; n_sessions_day := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) / 7 INTO :v_task_runs_day FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY WHERE SCHEDULED_TIME >= DATEADD(day, -7, CURRENT_TIMESTAMP());
  EXCEPTION WHEN OTHER THEN
    v_task_runs_day := 0; n_task_runs_day := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_task_runs_day IS NULL) THEN v_task_runs_day := 0; n_task_runs_day := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) / 7 INTO :v_files_loaded_day FROM SNOWFLAKE.ACCOUNT_USAGE.COPY_HISTORY WHERE LAST_LOAD_TIME >= DATEADD(day, -7, CURRENT_TIMESTAMP());
  EXCEPTION WHEN OTHER THEN
    v_files_loaded_day := 0; n_files_loaded_day := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_files_loaded_day IS NULL) THEN v_files_loaded_day := 0; n_files_loaded_day := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) / 7 INTO :v_dt_refreshes_day FROM SNOWFLAKE.ACCOUNT_USAGE.DYNAMIC_TABLE_REFRESH_HISTORY WHERE REFRESH_START_TIME >= DATEADD(day, -7, CURRENT_TIMESTAMP());
  EXCEPTION WHEN OTHER THEN
    v_dt_refreshes_day := 0; n_dt_refreshes_day := 'n/a, using default: ' || SQLERRM;
  END;
  IF (v_dt_refreshes_day IS NULL) THEN v_dt_refreshes_day := 0; n_dt_refreshes_day := 'n/a, no data returned, using default'; END IF;
  BEGIN
    SELECT COUNT(*) INTO :v_org FROM (SELECT 1 FROM SNOWFLAKE.ORGANIZATION_USAGE.USAGE_IN_CURRENCY_DAILY LIMIT 1);
    v_org := 1;
  EXCEPTION WHEN OTHER THEN
    v_org := 0; n_org := 'n/a, requires an organization account: ' || SQLERRM;
  END;
  BEGIN -- actual vs estimate, only when DSOA is already installed; averaged over the days that have data
    SELECT SUM(CREDITS_USED), COUNT(DISTINCT TO_DATE(START_TIME)) INTO :v_actual_credits, :v_actual_days
      FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY
      WHERE WAREHOUSE_NAME = 'DTAGENT_WH' AND START_TIME >= DATEADD(day, -7, CURRENT_TIMESTAMP());
    IF (v_actual_days > 0) THEN
      v_actual_credits := v_actual_credits / v_actual_days;
      n_actual_credits := 'measured, average over ' || v_actual_days || ' day(s) with data';
    ELSE
      v_actual_credits := NULL; n_actual_credits := 'not installed';
    END IF;
  EXCEPTION WHEN OTHER THEN
    n_actual_credits := 'n/a: ' || SQLERRM;
  END;
  BEGIN
    SELECT SUM(f.value::NUMBER), COUNT(DISTINCT TO_DATE(l.PROCESS_TIME)) INTO :v_actual_records, :v_actual_rec_days
      FROM DTAGENT_DB.STATUS.PROCESSED_MEASUREMENTS_LOG l, LATERAL FLATTEN(l.ENTRIES_COUNT, RECURSIVE => TRUE) f
      WHERE l.PROCESS_TIME >= DATEADD(day, -7, CURRENT_TIMESTAMP())
        AND f.key IN ('log_lines', 'metrics', 'events', 'spans') AND IS_INTEGER(f.value);
    IF (v_actual_rec_days > 0) THEN
      v_actual_records := v_actual_records / v_actual_rec_days;
      n_actual_records := 'measured, average over ' || v_actual_rec_days || ' day(s) with data';
    ELSE
      v_actual_records := NULL; n_actual_records := 'not installed';
    END IF;
  EXCEPTION WHEN OTHER THEN
    n_actual_records := 'n/a: ' || SQLERRM;
  END;
  res := (
    WITH
    sig(plugin, signal, records_day, bytes_per_record) AS (
      SELECT 'active_queries', 'logs', ((240 * (:v_queries_day * 0.1 / 240) * 1 + 240))::FLOAT, 1363.0
      UNION ALL
      SELECT 'active_queries', 'metrics', ((240 * (:v_queries_day * 0.1 / 240) * 5 + 240))::FLOAT, 443.9
      UNION ALL
      SELECT 'active_queries', 'spans', ((240 * (:v_queries_day * 0.1 / 240) * 1))::FLOAT, 3900.2
      UNION ALL
      SELECT 'active_queries', 'bizevents', ((480))::FLOAT, 588.5
      UNION ALL
      SELECT 'budgets', 'logs', ((1 * (:v_const * 1) * 1 + 1))::FLOAT, 798.0
      UNION ALL
      SELECT 'budgets', 'metrics', ((1 * (:v_const * 1) * 2 + 1))::FLOAT, 429.3
      UNION ALL
      SELECT 'budgets', 'events', ((1 * (:v_const * 1) * 1))::FLOAT, 964.0
      UNION ALL
      SELECT 'budgets', 'bizevents', ((2))::FLOAT, 572.5
      UNION ALL
      SELECT 'cold_tables', 'logs', ((1 * (:v_tables_in_scope * 0.2) * 1 + 1))::FLOAT, 876.0
      UNION ALL
      SELECT 'cold_tables', 'metrics', ((1 * (:v_tables_in_scope * 0.2) * 2 + 1))::FLOAT, 452.8
      UNION ALL
      SELECT 'cold_tables', 'bizevents', ((2))::FLOAT, 582.5
      UNION ALL
      SELECT 'data_schemas', 'logs', ((3))::FLOAT, 1973.7
      UNION ALL
      SELECT 'data_schemas', 'metrics', ((3))::FLOAT, 518.9
      UNION ALL
      SELECT 'data_schemas', 'events', ((3 * (:v_ddl_day * 1 / 3) * 1))::FLOAT, 1158.5
      UNION ALL
      SELECT 'data_schemas', 'bizevents', ((6))::FLOAT, 584.5
      UNION ALL
      SELECT 'data_volume', 'logs', ((6))::FLOAT, 1973.7
      UNION ALL
      SELECT 'data_volume', 'metrics', ((6 * (:v_tables_in_scope * 1) * 3 + 6))::FLOAT, 461.9
      UNION ALL
      SELECT 'data_volume', 'events', ((6 * (:v_tables_in_scope * 1) * 1))::FLOAT, 825.0
      UNION ALL
      SELECT 'data_volume', 'bizevents', ((12))::FLOAT, 582.5
      UNION ALL
      SELECT 'dynamic_tables', 'logs', ((48 * (:v_dynamic_tables * 1) * 1 + 48 + 48 * (:v_dt_refreshes_day * 1 / 48) * 1 + 48))::FLOAT, 1349.2
      UNION ALL
      SELECT 'dynamic_tables', 'metrics', ((48 * (:v_dynamic_tables * 1) * 4 + 48 + 48 * (:v_dt_refreshes_day * 1 / 48) * 6 + 48))::FLOAT, 464.6
      UNION ALL
      SELECT 'dynamic_tables', 'bizevents', ((96))::FLOAT, 588.5
      UNION ALL
      SELECT 'event_log', 'logs', ((48 * LEAST((:v_log_rows_day * 1 / 48), 10000) * 1 + 48 + 48 + 48))::FLOAT, 2339.0
      UNION ALL
      SELECT 'event_log', 'metrics', ((48 + 48 + 48 * LEAST((:v_metric_rows_day * 1 / 48), 10000) * 1 + 48))::FLOAT, 1053.2
      UNION ALL
      SELECT 'event_log', 'spans', ((48 * LEAST((:v_span_rows_day * 1 / 48), 10000) * 1))::FLOAT, 1422.5
      UNION ALL
      SELECT 'event_log', 'bizevents', ((96))::FLOAT, 578.5
      UNION ALL
      SELECT 'login_history', 'logs', ((48 * (:v_logins_day * 1 / 48) * 1 + 48 + 48 * (:v_sessions_day * 1 / 48) * 1 + 48))::FLOAT, 761.0
      UNION ALL
      SELECT 'login_history', 'metrics', ((48 + 48))::FLOAT, 518.9
      UNION ALL
      SELECT 'login_history', 'bizevents', ((96))::FLOAT, 586.5
      UNION ALL
      SELECT 'metering', 'logs', ((24 * (:v_warehouses * 1) * 1 + 24))::FLOAT, 866.5
      UNION ALL
      SELECT 'metering', 'metrics', ((24 * (:v_warehouses * 1) * 6 + 24))::FLOAT, 327.3
      UNION ALL
      SELECT 'metering', 'bizevents', ((48))::FLOAT, 576.5
      UNION ALL
      SELECT 'org_costs', 'logs', ((4 * (:v_const * 50) * 1 + 4) * :v_org)::FLOAT, 769.7
      UNION ALL
      SELECT 'org_costs', 'metrics', ((4 * (:v_const * 50) * 1 + 4) * :v_org)::FLOAT, 393.3
      UNION ALL
      SELECT 'org_costs', 'bizevents', ((8) * :v_org)::FLOAT, 578.5
      UNION ALL
      SELECT 'query_history', 'logs', ((48 * (:v_queries_day * 1 / 48) * 1 + 48))::FLOAT, 10826.7
      UNION ALL
      SELECT 'query_history', 'metrics', ((48 * (:v_queries_day * 1 / 48) * 37 + 48))::FLOAT, 555.5
      UNION ALL
      SELECT 'query_history', 'spans', ((48 * (:v_queries_day * 1 / 48) * 1))::FLOAT, 6984.3
      UNION ALL
      SELECT 'query_history', 'bizevents', ((96))::FLOAT, 586.5
      UNION ALL
      SELECT 'resource_monitors', 'logs', ((48 * (:v_resource_monitors * 1) * 1 + 48))::FLOAT, 1973.7
      UNION ALL
      SELECT 'resource_monitors', 'metrics', ((48 * (:v_resource_monitors * 1) * 5 + 48))::FLOAT, 353.4
      UNION ALL
      SELECT 'resource_monitors', 'events', ((48 * (:v_resource_monitors * 1) * 0.1))::FLOAT, 1406.9
      UNION ALL
      SELECT 'resource_monitors', 'bizevents', ((96))::FLOAT, 594.5
      UNION ALL
      SELECT 'shares', 'logs', ((48 * (:v_share_grants_out * 1) * 1 + 48 + 48 * (:v_tables_in_shares * 1) * 1 + 48))::FLOAT, 949.6
      UNION ALL
      SELECT 'shares', 'metrics', ((48 + 48))::FLOAT, 518.9
      UNION ALL
      SELECT 'shares', 'bizevents', ((96))::FLOAT, 572.5
      UNION ALL
      SELECT 'snowpipes', 'logs', ((288 * (:v_pipes * 1) * 1 + 288 + 288 * (:v_files_loaded_day * 1 / 288) * 1 + 288))::FLOAT, 1186.3
      UNION ALL
      SELECT 'snowpipes', 'metrics', ((288 * (:v_pipes * 1) * 2 + 288 + 288 * (:v_files_loaded_day * 1 / 288) * 8 + 288))::FLOAT, 537.2
      UNION ALL
      SELECT 'snowpipes', 'bizevents', ((576))::FLOAT, 578.5
      UNION ALL
      SELECT 'table_health', 'logs', ((4))::FLOAT, 1973.7
      UNION ALL
      SELECT 'table_health', 'metrics', ((4 * LEAST(:v_tables_in_scope * 0.1, 500) * 13 + 4))::FLOAT, 474.2
      UNION ALL
      SELECT 'table_health', 'bizevents', ((8))::FLOAT, 584.5
      UNION ALL
      SELECT 'tasks', 'logs', ((24 * (:v_task_runs_day * 1 / 24) * 1 + 24))::FLOAT, 1011.8
      UNION ALL
      SELECT 'tasks', 'metrics', ((24))::FLOAT, 361.0
      UNION ALL
      SELECT 'tasks', 'events', ((24 * (:v_task_runs_day * 1 / 24) * 0.05))::FLOAT, 1187.5
      UNION ALL
      SELECT 'tasks', 'bizevents', ((48))::FLOAT, 570.5
      UNION ALL
      SELECT 'trust_center', 'logs', ((2 * (:v_trust_center_findings * 1) * 1 + 2))::FLOAT, 1375.0
      UNION ALL
      SELECT 'trust_center', 'metrics', ((2 * (:v_trust_center_findings * 1) * 1 + 2))::FLOAT, 493.5
      UNION ALL
      SELECT 'trust_center', 'bizevents', ((4))::FLOAT, 584.5
      UNION ALL
      SELECT 'users', 'logs', ((1 * (:v_users * 1) * 1 + 1))::FLOAT, 792.1
      UNION ALL
      SELECT 'users', 'metrics', ((1))::FLOAT, 518.9
      UNION ALL
      SELECT 'users', 'events', ((1 * (:v_users * 1) * 0.05))::FLOAT, 908.4
      UNION ALL
      SELECT 'users', 'bizevents', ((2))::FLOAT, 570.5
      UNION ALL
      SELECT 'warehouse_usage', 'logs', ((24 * (:v_warehouses * 1) * 1 + 24))::FLOAT, 766.2
      UNION ALL
      SELECT 'warehouse_usage', 'metrics', ((24 * (:v_warehouses * 1) * 7 + 24))::FLOAT, 317.1
      UNION ALL
      SELECT 'warehouse_usage', 'bizevents', ((48))::FLOAT, 590.5
    ),
    gaps AS (
      SELECT 'active_queries' AS plugin, IFF(:n_queries_day <> 'measured', 'queries_day ', '') AS gap
      UNION ALL
      SELECT 'cold_tables' AS plugin, IFF(:n_tables_in_scope <> 'measured', 'tables_in_scope ', '') AS gap
      UNION ALL
      SELECT 'data_schemas' AS plugin, IFF(:n_ddl_day <> 'measured', 'ddl_day ', '') AS gap
      UNION ALL
      SELECT 'data_volume' AS plugin, IFF(:n_tables_in_scope <> 'measured', 'tables_in_scope ', '') AS gap
      UNION ALL
      SELECT 'dynamic_tables' AS plugin, IFF(:n_dt_refreshes_day <> 'measured', 'dt_refreshes_day ', '') || IFF(:n_dynamic_tables <> 'measured', 'dynamic_tables ', '') AS gap
      UNION ALL
      SELECT 'event_log' AS plugin, IFF(:n_log_rows_day <> 'measured', 'log_rows_day ', '') || IFF(:n_metric_rows_day <> 'measured', 'metric_rows_day ', '') || IFF(:n_span_rows_day <> 'measured', 'span_rows_day ', '') AS gap
      UNION ALL
      SELECT 'login_history' AS plugin, IFF(:n_logins_day <> 'measured', 'logins_day ', '') || IFF(:n_sessions_day <> 'measured', 'sessions_day ', '') AS gap
      UNION ALL
      SELECT 'metering' AS plugin, IFF(:n_warehouses <> 'measured', 'warehouses ', '') AS gap
      UNION ALL
      SELECT 'query_history' AS plugin, IFF(:n_queries_day <> 'measured', 'queries_day ', '') AS gap
      UNION ALL
      SELECT 'resource_monitors' AS plugin, IFF(:n_resource_monitors <> 'measured', 'resource_monitors ', '') AS gap
      UNION ALL
      SELECT 'shares' AS plugin, IFF(:n_share_grants_out <> 'measured', 'share_grants_out ', '') || IFF(:n_tables_in_shares <> 'measured', 'tables_in_shares ', '') AS gap
      UNION ALL
      SELECT 'snowpipes' AS plugin, IFF(:n_files_loaded_day <> 'measured', 'files_loaded_day ', '') || IFF(:n_pipes <> 'measured', 'pipes ', '') AS gap
      UNION ALL
      SELECT 'table_health' AS plugin, IFF(:n_tables_in_scope <> 'measured', 'tables_in_scope ', '') AS gap
      UNION ALL
      SELECT 'tasks' AS plugin, IFF(:n_task_runs_day <> 'measured', 'task_runs_day ', '') AS gap
      UNION ALL
      SELECT 'trust_center' AS plugin, IFF(:n_trust_center_findings <> 'measured', 'trust_center_findings ', '') AS gap
      UNION ALL
      SELECT 'users' AS plugin, IFF(:n_users <> 'measured', 'users ', '') AS gap
      UNION ALL
      SELECT 'warehouse_usage' AS plugin, IFF(:n_warehouses <> 'measured', 'warehouses ', '') AS gap
    ),
    sf(plugin, status, default_on, deprecated, needs_org, standalone, alloc_org, alloc_no_org, note) AS (
      SELECT * FROM VALUES
      ('active_queries', 'on by default', 1, 0, 0, 7.933333, 3.197758, 3.216974, ''),
      ('budgets', 'off by default', 0, 0, 0, 0.036111, 0.014556, 0.014643, ''),
      ('cold_tables', 'on by default', 1, 0, 0, 0.0475, 0.019146, 0.019261, ''),
      ('data_schemas', 'on by default', 1, 0, 0, 0.14, 0.056431, 0.05677, ''),
      ('data_volume', 'on by default', 1, 0, 0, 0.216667, 0.087334, 0.087859, ''),
      ('dynamic_tables', 'on by default', 1, 0, 0, 1.64, 0.661049, 0.665022, ''),
      ('event_log', 'on by default', 1, 0, 0, 1.626667, 0.655675, 0.659615, ''),
      ('event_usage', 'deprecated', 0, 1, 0, NULL, NULL, NULL, 'deprecated since 0.9.5, replaced by metering, not counted'),
      ('login_history', 'on by default', 1, 0, 0, 1.72, 0.693295, 0.697462, ''),
      ('metering', 'on by default', 1, 0, 0, 0.793333, 0.319776, 0.321697, ''),
      ('org_costs', 'off by default', 0, 0, 1, 0.144444, 0.058222, 0, 'n/a, requires org account'),
      ('query_history', 'on by default', 1, 0, 0, 3.4, 1.370468, 1.378703, ''),
      ('resource_monitors', 'on by default', 1, 0, 0, 1.613333, 0.6503, 0.654208, ''),
      ('shares', 'on by default', 1, 0, 0, 1.853333, 0.747039, 0.751528, ''),
      ('snowpipes', 'on by default', 1, 0, 0, 0.966667, 0.389643, 0.391984, ''),
      ('table_health', 'off by default', 0, 0, 0, 0.144444, 0.058222, 0.058572, ''),
      ('tasks', 'on by default', 1, 0, 0, 0.84, 0.338586, 0.340621, ''),
      ('trust_center', 'on by default', 1, 0, 0, 0.065556, 0.026424, 0.026583, ''),
      ('users', 'on by default', 1, 0, 0, 0.039167, 0.015787, 0.015882, ''),
      ('warehouse_usage', 'on by default', 1, 0, 0, 0.96, 0.386956, 0.389281, '')
    ),
    priced AS (
      SELECT plugin, signal, records_day,
        records_day * bytes_per_record / 1073741824 AS gib_day,
        IFF(signal = 'metrics', records_day * 30 / 100000 * :p_metrics_100k,
            records_day * bytes_per_record / 1073741824 * 30 * CASE signal
              WHEN 'logs' THEN :p_logs_gib WHEN 'spans' THEN :p_spans_gib
              WHEN 'events' THEN :p_events_gib ELSE :p_bizevents_gib END) AS usd_ingest_month
      FROM sig
    ),
    costed AS (
      SELECT plugin, signal, records_day, gib_day, gib_day * :p_retention_days AS gib_retained,
        usd_ingest_month + gib_day * 15 * :p_retain_gib_day * 30 AS usd_month_1,
        usd_ingest_month + gib_day * :p_retention_days * :p_retain_gib_day * 30 AS usd_month_steady
      FROM priced
    ),
    by_plugin AS (
      SELECT s.plugin,
        s.status || IFF(s.note <> '' AND s.deprecated = 0, ', ' || s.note, IFF(s.deprecated = 1, ', ' || s.note, ''))
          || IFF(COALESCE(g.gap, '') <> '', ' - ESTIMATE INCOMPLETE, input n/a: ' || RTRIM(g.gap), '') AS status_note,
        s.default_on, s.deprecated, s.needs_org,
        SUM(c.records_day) AS records_day, SUM(c.gib_day) AS gib_day, SUM(c.gib_retained) AS gib_retained,
        SUM(c.usd_month_1) AS usd_month_1, SUM(c.usd_month_steady) AS usd_month_steady,
        IFF(s.deprecated = 1, NULL, IFF(:v_org = 1, s.alloc_org, s.alloc_no_org)) AS sf_alloc,
        IFF(s.deprecated = 1 OR (s.needs_org = 1 AND :v_org = 0), NULL, s.standalone) AS sf_standalone
      FROM sf s LEFT JOIN costed c ON c.plugin = s.plugin LEFT JOIN gaps g ON g.plugin = s.plugin
      GROUP BY s.plugin, g.gap, s.status, s.note, s.default_on, s.deprecated, s.needs_org, s.alloc_org, s.alloc_no_org, s.standalone
    ),
    top_signal AS (
      SELECT plugin, signal, usd_month_steady / NULLIFZERO(SUM(usd_month_steady) OVER (PARTITION BY plugin)) AS share
      FROM costed QUALIFY ROW_NUMBER() OVER (PARTITION BY plugin ORDER BY usd_month_steady DESC) = 1
    ),
    totals AS (
      SELECT SUM(records_day) AS records_day, SUM(gib_day) AS gib_day, SUM(gib_retained) AS gib_retained,
        SUM(usd_month_1) AS usd_month_1, SUM(usd_month_steady) AS usd_month_steady, SUM(sf_alloc) AS sf_alloc, SUM(sf_standalone) AS sf_standalone,
        SUM(IFF(default_on = 1, records_day, 0)) AS d_records, SUM(IFF(default_on = 1, gib_day, 0)) AS d_gib,
        SUM(IFF(default_on = 1, gib_retained, 0)) AS d_retained, SUM(IFF(default_on = 1, usd_month_1, 0)) AS d_m1,
        SUM(IFF(default_on = 1, usd_month_steady, 0)) AS d_steady
      FROM by_plugin
    ),
    out(section, item, signal, note, value, records_day, gib_day, gib_retained, usd_month_1, usd_month_steady, sf_alloc, sf_standalone, sort_key) AS (
      SELECT '1 HEADER', 'Rate card (editable)', NULL, 'logs ' || :p_logs_gib || ', spans ' || :p_spans_gib || ', events ' || :p_events_gib
        || ', bizevents ' || :p_bizevents_gib || ' per GiB; metrics ' || :p_metrics_100k || ' per 100k data points; retain ' || :p_retain_gib_day
        || ' per GiB-day', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, -1
      UNION ALL SELECT '1 HEADER', 'DSOA cost estimate - DSOA defaults, all plugins enabled, no config', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0
      UNION ALL SELECT '1 HEADER', 'Rate card as of 2026-11-02 (USD), retention 365 days - edit the rate-card block at the top to re-price', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1
      UNION ALL SELECT '1 HEADER', 'Dynatrace query cost (dashboards, notebooks, workflows, ad-hoc DQL) is NOT included: it depends on how the data is used', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2
      UNION ALL SELECT '1 HEADER', 'Snowflake cost covers DTAGENT_WH only (credits); Snowflake event table ingest and cloud services above the 10% adjustment are reported separately', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3
      UNION ALL SELECT '1 HEADER', 'Run durations per plugin are model constants, volumes are modelled from measured object counts and workload - see docs/INSTALL.md', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4
      UNION ALL SELECT '2 INPUT', 'tables_in_scope', NULL, :n_tables_in_scope, :v_tables_in_scope, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0
      UNION ALL SELECT '2 INPUT', 'dynamic_tables', NULL, :n_dynamic_tables, :v_dynamic_tables, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1
      UNION ALL SELECT '2 INPUT', 'pipes', NULL, :n_pipes, :v_pipes, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2
      UNION ALL SELECT '2 INPUT', 'warehouses', NULL, :n_warehouses, :v_warehouses, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3
      UNION ALL SELECT '2 INPUT', 'resource_monitors', NULL, :n_resource_monitors, :v_resource_monitors, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4
      UNION ALL SELECT '2 INPUT', 'users', NULL, :n_users, :v_users, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5
      UNION ALL SELECT '2 INPUT', 'share_grants_out', NULL, :n_share_grants_out, :v_share_grants_out, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6
      UNION ALL SELECT '2 INPUT', 'tables_in_shares', NULL, :n_tables_in_shares, :v_tables_in_shares, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 7
      UNION ALL SELECT '2 INPUT', 'trust_center_findings', NULL, :n_trust_center_findings, :v_trust_center_findings, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8
      UNION ALL SELECT '2 INPUT', 'queries_day', NULL, :n_queries_day, :v_queries_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9
      UNION ALL SELECT '2 INPUT', 'slow_queries_day', NULL, :n_slow_queries_day, :v_slow_queries_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 10
      UNION ALL SELECT '2 INPUT', 'log_rows_day', NULL, :n_log_rows_day, :v_log_rows_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 11
      UNION ALL SELECT '2 INPUT', 'span_rows_day', NULL, :n_span_rows_day, :v_span_rows_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12
      UNION ALL SELECT '2 INPUT', 'metric_rows_day', NULL, :n_metric_rows_day, :v_metric_rows_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 13
      UNION ALL SELECT '2 INPUT', 'logins_day', NULL, :n_logins_day, :v_logins_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 14
      UNION ALL SELECT '2 INPUT', 'sessions_day', NULL, :n_sessions_day, :v_sessions_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 15
      UNION ALL SELECT '2 INPUT', 'task_runs_day', NULL, :n_task_runs_day, :v_task_runs_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16
      UNION ALL SELECT '2 INPUT', 'files_loaded_day', NULL, :n_files_loaded_day, :v_files_loaded_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 17
      UNION ALL SELECT '2 INPUT', 'ddl_day', NULL, :n_ddl_day, :v_ddl_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18
      UNION ALL SELECT '2 INPUT', 'dt_refreshes_day', NULL, :n_dt_refreshes_day, :v_dt_refreshes_day, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 19
      UNION ALL SELECT '3 PLUGIN', plugin, NULL, status_note, NULL, records_day, gib_day, gib_retained, usd_month_1, usd_month_steady,
        sf_alloc, sf_standalone, ROW_NUMBER() OVER (ORDER BY plugin) FROM by_plugin
      UNION ALL SELECT '4 PLUGIN SIGNAL', plugin, signal, NULL, NULL, records_day, gib_day, gib_retained, usd_month_1, usd_month_steady,
        NULL, NULL, ROW_NUMBER() OVER (ORDER BY plugin, signal) FROM costed
      UNION ALL SELECT '0 TOTAL', 'all plugins (incl. off by default)', NULL, 'every plugin that is not deprecated, including off-by-default ones; org_costs only on an organization account', NULL, records_day, gib_day, gib_retained,
        usd_month_1, usd_month_steady, sf_alloc, sf_standalone, 0 FROM totals
      UNION ALL SELECT '0 TOTAL', 'default install', NULL, 'only plugins enabled in the shipped config; excludes budgets, table_health, org_costs, event_usage', NULL, d_records, d_gib, d_retained, d_m1, d_steady,
        9.746667, NULL, 1 FROM totals
      UNION ALL SELECT '5 RESOURCE MONITOR', 'core.snowflake.resource_monitor.credit_quota (all plugins)', NULL,
        'estimated credits/day x 1.4, rounded up', CEIL(sf_alloc * 1.4), NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0 FROM totals
      UNION ALL SELECT '5 RESOURCE MONITOR', 'core.snowflake.resource_monitor.credit_quota (default install)', NULL,
        'estimated credits/day x 1.4, rounded up', CEIL(9.746667 * 1.4), NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1 FROM totals
      UNION ALL SELECT '6 TOP COST DRIVER', p.plugin, t.signal, 'Dynatrace $/month at steady state, ' || ROUND(t.share * 100) || '% from ' || t.signal,
        NULL, p.records_day, p.gib_day, p.gib_retained, p.usd_month_1, p.usd_month_steady, p.sf_alloc, p.sf_standalone,
        ROW_NUMBER() OVER (ORDER BY p.usd_month_steady DESC NULLS LAST)
        FROM by_plugin p JOIN top_signal t ON t.plugin = p.plugin
        QUALIFY ROW_NUMBER() OVER (ORDER BY p.usd_month_steady DESC NULLS LAST) <= 3
      UNION ALL SELECT '7 ACTUAL VS ESTIMATE', 'DTAGENT_WH credits/day', NULL, 'actual: ' || :n_actual_credits, :v_actual_credits, NULL, NULL, NULL, NULL, NULL,
        sf_alloc, NULL, 0 FROM totals
      UNION ALL SELECT '7 ACTUAL VS ESTIMATE', 'records/day logged in PROCESSED_MEASUREMENTS_LOG (logs, metrics, events, spans; no bizevents)', NULL,
        'actual: ' || :n_actual_records, :v_actual_records,
        (SELECT SUM(records_day) FROM costed WHERE signal <> 'bizevents'), NULL, NULL, NULL, NULL, NULL, NULL, 1 FROM totals
    )
    SELECT section AS SECTION, item AS ITEM, signal AS SIGNAL, note AS NOTE, value AS VALUE,
      ROUND(records_day) AS RECORDS_DAY, ROUND(gib_day, 4) AS DT_GIB_INGESTED_DAY, ROUND(gib_retained, 3) AS DT_GIB_RETAINED_STEADY,
      ROUND(usd_month_1, 2) AS DT_USD_MONTH_1, ROUND(usd_month_steady, 2) AS DT_USD_MONTH_STEADY,
      ROUND(sf_alloc, 3) AS SF_CREDITS_DAY_ALLOCATED, ROUND(sf_standalone, 3) AS SF_CREDITS_DAY_STANDALONE,
      ROUND(sf_alloc * 30, 1) AS SF_CREDITS_MONTH_ALLOCATED
    FROM out ORDER BY section, sort_key
  );
  RETURN TABLE(res);
END;
$$;
